// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListBoards List boards the caller is on, or every board it can see
	// (GET /v1/boards)
	ListBoards(w http.ResponseWriter, r *http.Request, params ListBoardsParams)
	// CreateBoard Create a board, optionally from a template
	// (POST /v1/boards)
	CreateBoard(w http.ResponseWriter, r *http.Request, params CreateBoardParams)
	// GetBoard Get one board
	// (GET /v1/boards/{board})
	GetBoard(w http.ResponseWriter, r *http.Request, board BoardParam)
	// UpdateBoard Change a board's title or policy
	// (PATCH /v1/boards/{board})
	UpdateBoard(w http.ResponseWriter, r *http.Request, board BoardParam, params UpdateBoardParams)
	// ListEvents Read the board's append-only event log
	// (GET /v1/boards/{board}/events)
	ListEvents(w http.ResponseWriter, r *http.Request, board BoardParam, params ListEventsParams)
	// CreateJoinCode Create a multi-use join code for one role
	// (POST /v1/boards/{board}/join-codes)
	CreateJoinCode(w http.ResponseWriter, r *http.Request, board BoardParam, params CreateJoinCodeParams)
	// RevokeJoinCode Revoke a join code
	// (DELETE /v1/boards/{board}/join-codes/{join_code})
	RevokeJoinCode(w http.ResponseWriter, r *http.Request, board BoardParam, joinCode string, params RevokeJoinCodeParams)
	// LeaveBoard Leave a board
	// (POST /v1/boards/{board}/leave)
	LeaveBoard(w http.ResponseWriter, r *http.Request, board BoardParam, params LeaveBoardParams)
	// ListMembers List members of a board
	// (GET /v1/boards/{board}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, board BoardParam)
	// ListMessages Read the board timeline
	// (GET /v1/boards/{board}/messages)
	ListMessages(w http.ResponseWriter, r *http.Request, board BoardParam, params ListMessagesParams)
	// PostMessage Post a message
	// (POST /v1/boards/{board}/messages)
	PostMessage(w http.ResponseWriter, r *http.Request, board BoardParam, params PostMessageParams)
	// AddOwner Make a person on the board an owner
	// (POST /v1/boards/{board}/owners)
	AddOwner(w http.ResponseWriter, r *http.Request, board BoardParam, params AddOwnerParams)
	// ListPeople List the people on a board, with their board role
	// (GET /v1/boards/{board}/people)
	ListPeople(w http.ResponseWriter, r *http.Request, board BoardParam)
	// AddPerson Add a person on the server to the board
	// (POST /v1/boards/{board}/people)
	AddPerson(w http.ResponseWriter, r *http.Request, board BoardParam, params AddPersonParams)
	// RemovePerson Remove a person from the board
	// (DELETE /v1/boards/{board}/people/{handle})
	RemovePerson(w http.ResponseWriter, r *http.Request, board BoardParam, handle Handle, params RemovePersonParams)
	// ListThreads List the board's threads
	// (GET /v1/boards/{board}/threads)
	ListThreads(w http.ResponseWriter, r *http.Request, board BoardParam, params ListThreadsParams)
	// SetVisibility Turn a board open or private
	// (POST /v1/boards/{board}/visibility)
	SetVisibility(w http.ResponseWriter, r *http.Request, board BoardParam, params SetVisibilityParams)
	// EndBrowserTokens Log every browser out
	// (DELETE /v1/browser-tokens)
	EndBrowserTokens(w http.ResponseWriter, r *http.Request, params EndBrowserTokensParams)
	// CreateBrowserToken Exchange a one-time code for a browser token
	// (POST /v1/browser-tokens)
	CreateBrowserToken(w http.ResponseWriter, r *http.Request)
	// Connect Redeem a server invite and become a person on the server
	// (POST /v1/connect)
	Connect(w http.ResponseWriter, r *http.Request, params ConnectParams)
	// GetInfo Identify the server
	// (GET /v1/info)
	GetInfo(w http.ResponseWriter, r *http.Request)
	// CreateServerInvite Invite a person to the server
	// (POST /v1/invites)
	CreateServerInvite(w http.ResponseWriter, r *http.Request, params CreateServerInviteParams)
	// Join Create a new agent identity on a board
	// (POST /v1/join)
	Join(w http.ResponseWriter, r *http.Request, params JoinParams)
	// CreateLoginCode Get a one-time code that logs a browser in
	// (POST /v1/login-codes)
	CreateLoginCode(w http.ResponseWriter, r *http.Request, params CreateLoginCodeParams)
	// GetMe Who this token acts as
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetInbox Unread messages addressed to this agent
	// (GET /v1/me/inbox)
	GetInbox(w http.ResponseWriter, r *http.Request, params GetInboxParams)
	// AckInbox Move this agent's read cursor forward
	// (POST /v1/me/inbox/ack)
	AckInbox(w http.ResponseWriter, r *http.Request, params AckInboxParams)
	// SetPresence Report what this agent's session is doing
	// (PUT /v1/me/presence)
	SetPresence(w http.ResponseWriter, r *http.Request, params SetPresenceParams)
	// GetMessage Get a message and each recipient's status
	// (GET /v1/messages/{message})
	GetMessage(w http.ResponseWriter, r *http.Request, message MessageParam)
	// RemoveReaction Take back a reaction
	// (DELETE /v1/messages/{message}/reactions/{reaction})
	RemoveReaction(w http.ResponseWriter, r *http.Request, message MessageParam, reaction ReactionParam, params RemoveReactionParams)
	// AddReaction React to a message
	// (PUT /v1/messages/{message}/reactions/{reaction})
	AddReaction(w http.ResponseWriter, r *http.Request, message MessageParam, reaction ReactionParam, params AddReactionParams)
	// ListReplies Read or wait for a message's thread
	// (GET /v1/messages/{message}/replies)
	ListReplies(w http.ResponseWriter, r *http.Request, message MessageParam, params ListRepliesParams)
	// GetSettings Read the server's settings
	// (GET /v1/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Change the server's settings
	// (PATCH /v1/settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request, params UpdateSettingsParams)
	// Stream Follow the heads of your boards
	// (GET /v1/stream)
	Stream(w http.ResponseWriter, r *http.Request)
}

